  useEffect(()=>{load();api('/customers').then(r=>setCustomers(r.customers));api('/team').then(r=>setTeam(r.team.filter(u=>u.role==='technician'&&u.status==='active'))).catch(()=>{})},[]);
  const filtered=items.filter(x=>[x.code,x.title,x.customer_name,x.technician_name,x.city].join(' ').toLowerCase().includes(q.toLowerCase()));
