  async function save(e){e.preventDefault();setSaving(true);try{const payload={...form,assigned_to:form.assigned_to||null,scheduled_at:form.scheduled_at?localDateTimeToUtc(form.scheduled_at,form.timezone):null,expected_duration_minutes:form.expected_duration_minutes?Number(form.expected_duration_minutes):null,service_price:Number(form.service_price||0),country_code:form.country_code.toUpperCase(),currency:form.currency.toUpperCase()};await api(editing?`/orders/${editing.id}`:'/orders',{method:editing?'PATCH':'POST',body:JSON.stringify(payload)});setModal(false);setToast({message:editing?'تم تحديث تفاصيل المهمة.':'تم إنشاء التاسك وإسناده للفني.'});load()}catch(e){setToast({type:'error',message:e.message})}finally{setSaving(false)}}
  async function update(id,status){try{await api(`/orders/${id}`,{method:'PATCH',body:JSON.stringify({status})});load()}catch(e){setToast({type:'error',message:e.message})}}
  async function reviewPayment(o,action){try{let payload={action};if(action==='confirm'){const value=window.prompt(`إجمالي المبلغ الذي تأكدت من استلامه (${o.currency}):`,String(Number(o.paid_amount||0)+Number(o.collected_amount||0)));if(value===null)return;const paid_amount=Number(value);if(!Number.isFinite(paid_amount)||paid_amount<Number(o.paid_amount||0))throw new Error('أدخل إجماليًا صحيحًا لا يقل عن الدفعات السابقة.');payload.paid_amount=paid_amount;}else if(!window.confirm('رفض تسجيل التحصيل وإعادته إلى غير محصل؟'))return;await api(`/orders/${o.id}/payment`,{method:'PATCH',body:JSON.stringify(payload)});setToast({message:action==='confirm'?'تم تأكيد التحصيل.':'تم رفض تسجيل التحصيل.'});load()}catch(e){setToast({type:'error',message:e.message})}}
